import{_ as a,C as r,o as i,c as o,j as p,a as n,E as l,a6 as s}from"./chunks/framework.CnPv4DE1.js";const g=JSON.parse('{"title":"终结拖延症的 3 习惯晨间惯例","description":"","frontmatter":{"title":"终结拖延症的 3 习惯晨间惯例","originalTitle":"The 3-Habit Morning Routine To End Procrastination","date":"2022-04-27","originalUrl":"https://thedankoe.com/letters/the-3-habit-morning-routine-to-end-procrastination/","minutes":4,"sourceHash":"fb98598aaaed50db8013da8b69c57bac4a044d18a41d29ee81bf3177c5a51dbb","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-3-habit-morning-routine-to-end-procrastination/"}]]},"headers":[],"relativePath":"letters/the-3-habit-morning-routine-to-end-procrastination.md","filePath":"letters/the-3-habit-morning-routine-to-end-procrastination.md"}'),h={name:"letters/the-3-habit-morning-routine-to-end-procrastination.md"};function d(c,e,u,b,m,_){const t=r("ArticleMeta");return i(),o("div",null,[e[0]||(e[0]=p("h1",{id:"终结拖延症的-3-习惯晨间惯例",tabindex:"-1"},[n("终结拖延症的 3 习惯晨间惯例 "),p("a",{class:"header-anchor",href:"#终结拖延症的-3-习惯晨间惯例","aria-label":'Permalink to "终结拖延症的 3 习惯晨间惯例"'},"​")],-1)),l(t),e[1]||(e[1]=s('<p><a href="https://www.youtube.com/embed/K47AMrhlw4E?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我尝试过所有的晨间惯例。</p><p>我试过放慢节奏、冥想、阅读 30 分钟，以及诸如此类的所有事情。</p><p>但我总觉得自己落后了。</p><p>对等待着我的任务感到压力和焦虑。</p><p>这种能量会一直延续到我接下来的一天中——它们总是感觉不对劲。</p><p>经过多年的摸索，我发现我需要的仅仅是 3 个简单的习惯。</p><p>脑海中首要惦记着这 3 件事，减少了起床的阻力。</p><p>一旦我的早晨有了意图和目标——情况就截然不同了。</p><h2 id="_3-个习惯的晨间惯例" tabindex="-1">3 个习惯的晨间惯例 <a class="header-anchor" href="#_3-个习惯的晨间惯例" aria-label="Permalink to &quot;3 个习惯的晨间惯例&quot;">​</a></h2><p>早晨是神圣的。它们为你一整天定下基调。你晨间惯例的目的应该是产生能量。</p><p>我们希望在一整天里都携带并保持这种能量。</p><h3 id="出门散步" tabindex="-1">出门散步 <a class="header-anchor" href="#出门散步" aria-label="Permalink to &quot;出门散步&quot;">​</a></h3><p>我们都知道身体会跟随大脑，但大脑也可以跟随身体。</p><p>它们是相辅相成的。</p><p>如果你想为接下来的一天产生不可阻挡的势能，那就从活动身体开始。</p><p>最好是在户外进行。</p><blockquote><p>“清晨的散步是一整天的恩赐。”——亨利·大卫·梭罗 (Henry David Thoreau)。</p></blockquote><p>亨利说到点子上了。</p><p>你不仅完成了每天的部分步数，而且还让皮肤暴露在直射的阳光下。</p><p>如果你坚持这样做，这对于健康的昼夜节律生物学至关重要。</p><p>（这甚至有助于你养成更规律的睡眠习惯——也许你根本就不是什么夜猫子！）</p><p>你可以步行去咖啡馆，在你的公寓小区周围转转，或者去任何你喜欢的地方。</p><p>前一天晚上把它写在你的计划本上，这样在早上它就会是你首要考虑的事。</p><h3 id="_10-分钟创意训练" tabindex="-1">10 分钟创意训练 <a class="header-anchor" href="#_10-分钟创意训练" aria-label="Permalink to &quot;10 分钟创意训练&quot;">​</a></h3><p>让我们把势能的雪球越滚越大。让这一天绝不可能被视为一种浪费。</p><p>我最喜欢的晨间习惯是我这些年来一直在培养的一个。</p><p>它是写日记、做笔记和写作的结合。</p><p>它可以帮助你学得更快，训练你的创意肌肉，并拥有极度清晰的头脑。</p><p>（而且如果你是一名创作者，它能帮你为工作带来源源不断的灵感。）</p><p>你需要这么做。</p><p><strong>第 1 步）获取灵感</strong></p><p>阅读一篇文章、一篇浓缩书摘 (blink)、一句最喜欢的名言，或是书中的一页。</p><p>你也可以在晨间散步时听听有声书！</p><p>注意：这些内容应该与你的兴趣相符。</p><p>这将为你接下来的一天提供灵感。</p><p><strong>第 2 步）记录你的兴奋点</strong></p><p>多巴胺能将信号从噪音中分离出来。</p><p>在你阅读或倾听的过程中，写下那些吸引你注意力并让你感到有点兴奋的内容。</p><p>我在手机里一直开着一个笔记应用程序，我会把这些全写进去。</p><p><strong>第 3 步）写一个 3-5 条的要点总结</strong></p><p>这个总结里应该包含什么？</p><ul><li>关于你个人如何理解该主题的描述</li><li>个人经历和故事</li><li>脑海中浮现的其他想法</li></ul><p>给创作者的附加步骤</p><ul><li>写下与该主题相关的常见问题</li><li>写下解决该问题的好处</li><li>写下克服该问题的步骤</li></ul><p>现在，你拥有了一篇博客、一个帖子连载 (thread)、一篇订阅通讯，或是多条推文的大纲了。</p><p>（我就是这么写出这篇文章的。）</p><p><strong>第 4 步）一句话大想法</strong></p><p>这就是创造力发挥作用的地方了。</p><p>从你之前写过的所有内容中，写出一句单句总结。</p><p>发挥创意。试着以你最喜欢的名言那样的质量来写它。</p><p>我们为什么要这么做？</p><ul><li>它能激发创意思维</li><li>它能引导你的大脑进行模式识别</li><li>它向你证明，你可以做到原创且有深度</li></ul><p>随着你写下越来越多的大想法，这种能力只会产生复利效应。</p><p>如果你想要一份 10 分钟创意习惯的 7 天指导挑战，<a href="https://7daystogenius.com/" target="_blank" rel="noreferrer">点这里。</a></p><h3 id="高能一小时" tabindex="-1">高能一小时 <a class="header-anchor" href="#高能一小时" aria-label="Permalink to &quot;高能一小时&quot;">​</a></h3><p>到目前为止，我们已经度过了大约 20 分钟高效的早晨时光。</p><p>我们的身心已经准备好继续前进了。去迎接挑战。去进入心流。</p><p>接下来是我喜欢称之为“高能一小时”（The Power Hour）的环节（不，这不是那个喝酒游戏）。</p><blockquote><p>“幸福就是力量增长的感觉——是阻力被克服的感觉。”</p><p>——尼采 (Nietzsche)</p></blockquote><p>“高能一小时”是一个专门用来进行建设的 1 小时时间块。</p><p>没有分心。只有一个优先级。像激光一样专注。</p><p>把这当成是每天自动进步 1%。</p><p>你在构建什么？</p><p>个人自由。</p><ul><li>做你的副业</li><li>写一篇文章、帖子连载或一本书</li><li>创作社交媒体帖子</li><li>学习一项有市场价值的技能</li><li>去接触潜在客户</li></ul><p>你懂的，就是那些你曾经说过要开始做却一直没做的事……</p><p>我怎么知道该做些什么？</p><ul><li>写下你对未来的愿景</li><li>将其逆向拆解为一个 10 年目标</li><li>然后是 1 年目标</li><li>然后是月度目标</li></ul><p>现在，将你的“高能一小时”任务与那个月度目标对齐。</p><p>采取专注于基本面、能撬动杠杆的行动，从而实现每天自动进步 1%。这就是我设计 <a href="https://shop.thedankoe.com/planer" target="_blank" rel="noreferrer">高能计划本 (The Power Planner)</a> 的原因。</p><p>结束“高能一小时”后，你对未来会充满积极的感觉。</p><p>在这 1 小时内，你已经在大多数人还没醒来之前赢得了这一天。</p><p>那种感觉是无与伦比的。</p><p><strong>总结一下：</strong></p><ol><li>出门散步，活动身体并晒晒太阳。</li><li>花 10 分钟训练你的创意肌肉。</li><li>花 1 小时为你自己构建一个更好的未来。</li></ol><p>当你持之以恒地执行，6 个月后你回首往事时，会沉浸在自己取得的进步中。</p><hr><p><a href="/en/letters/the-3-habit-morning-routine-to-end-procrastination">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',79))])}const k=a(h,[["render",d]]);export{g as __pageData,k as default};
